def _cerro_fix_merged_audio_dtbos(out_dir, created):
	"""AOSPA cerro: make Lineage zte sound props win over MTP audio.

	fdtoverlaymerge keeps both zte and pineapple-audio fragments; ABL apply
	leaves MTP qcom,num-macros=4 / wsa-max-devs=2 / WSA audio-routing last.
	Keep audio techpack (symbols for AW882 overlays) and rewrite those MTP
	copies in-place via fix-cerro-audio-dtbo.py.
	"""
	fixer = os.path.join(os.path.dirname(os.path.abspath(__file__)),
				'fix-cerro-audio-dtbo.py')
	if not os.path.isfile(fixer):
		logging.warning('cerro audio fixup script missing: {}'.format(fixer))
		return
	targets = []
	for dt in created:
		name = os.path.basename(dt.filename)
		if 'zte-cerro' in name and name.endswith('.dtbo'):
			targets.append(dt.filename)
	# Also catch anything already on disk under out_dir
	if os.path.isdir(out_dir):
		for name in os.listdir(out_dir):
			if 'zte-cerro' in name and name.endswith('.dtbo'):
				path = os.path.join(out_dir, name)
				if path not in targets:
					targets.append(path)
	if not targets:
		logging.info('cerro: no zte-cerro merged dtbo to fix')
		return
	cmd = [sys.executable, fixer, '-v'] + targets
	logging.info('cerro: fixing audio props in {}'.format(' '.join(targets)))
	subprocess.run(cmd, check=True)

